@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#f4f4e9;--muted:#a9b5b1;--lime:#d8ff64;--teal:#7ce6ce;--orange:#ff9367;--glass:rgba(7,25,32,.78);--line:rgba(238,250,231,.16);font-family:'DM Sans',sans-serif;color:var(--ink);font-synthesis:none}*{box-sizing:border-box}html,body{height:100%;margin:0;background:#08212c;overflow:hidden}body{min-width:320px}button,a,input{font:inherit}button{color:inherit;cursor:pointer}#app{position:relative;width:100%;height:100dvh;min-height:570px;overflow:hidden;background:radial-gradient(ellipse at 68% 28%,#397b77 0,#134453 35%,#08212c 76%)}#court{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(4,17,22,.58) 0%,rgba(4,17,22,.1) 54%,rgba(4,17,22,.16) 100%),linear-gradient(0deg,rgba(3,14,20,.62),transparent 30%,rgba(3,14,20,.32))}.topbar{position:absolute;z-index:4;left:5.2%;right:5.2%;top:27px;height:40px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink);font:700 14px 'Space Grotesk',sans-serif;letter-spacing:1.55px}.brand-mark{width:32px;height:32px;border:1px solid rgba(216,255,100,.7);border-radius:11px 11px 11px 3px;color:var(--lime);font:700 20px 'Space Grotesk';display:grid;place-items:center;transform:rotate(-5deg)}.brand-light{font-weight:400;color:#a8c3bc}.top-stats{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:12px}.status-pill,.coin-pill{height:34px;border:1px solid var(--line);border-radius:20px;display:flex;align-items:center;padding:0 12px;gap:8px;background:rgba(6,25,31,.32);font:500 10px 'DM Mono',monospace;letter-spacing:1px}.status-pill i,.season-live i{width:6px;height:6px;border-radius:50%;background:var(--lime);box-shadow:0 0 9px var(--lime)}.coin-pill{font:700 13px 'Space Grotesk';letter-spacing:.3px}.coin-icon{color:var(--lime);font-size:15px}.icon-btn{width:36px;height:36px;background:rgba(5,24,30,.38);border:1px solid var(--line);border-radius:50%;color:var(--teal);font-size:17px}.screen{position:absolute;z-index:2;inset:0}.hidden{display:none!important}.lobby{pointer-events:none}.lobby>*{pointer-events:auto}.hero-copy{position:absolute;left:10.4%;top:22.3%;max-width:460px}.eyebrow{margin:0 0 15px;color:var(--teal);font:500 10px 'DM Mono',monospace;letter-spacing:2px}.eyebrow-line{display:inline-block;width:25px;height:1px;background:var(--teal);vertical-align:middle;margin-right:9px}.hero-copy h1{margin:0;font:700 clamp(56px,7vw,94px)/.86 'Space Grotesk',sans-serif;letter-spacing:-6px;color:#f4f4e9;text-shadow:0 5px 30px #1a4142}.hero-copy h1 em,.result-card h2 em{font-style:normal;color:var(--lime)}.hero-sub{margin:21px 0 27px;color:#c0d0c9;font-size:14px;line-height:1.6}.hero-actions{display:flex;align-items:center;gap:13px}.primary-btn{height:51px;min-width:171px;border:0;border-radius:5px;background:var(--lime);color:#132823;padding:0 17px 0 22px;display:flex;align-items:center;justify-content:space-between;gap:25px;font:700 11px 'DM Mono',monospace;letter-spacing:1.1px;transition:transform .18s,filter .18s}.primary-btn:hover{transform:translateY(-2px);filter:brightness(1.06)}.primary-btn b{font-size:19px;font-family:'DM Sans';font-weight:500}.round-play{width:48px;height:48px;border-radius:50%;border:1px solid rgba(236,246,225,.46);background:rgba(7,28,34,.3);font-size:12px;padding-left:4px;color:var(--ink)}.quick-label{font:500 8px/1.35 'DM Mono',monospace;letter-spacing:1px;color:#c7d7d0}.daily-reward{margin-top:33px;width:328px;min-height:59px;display:flex;align-items:center;gap:12px;padding:10px 11px;border:1px solid rgba(233,247,227,.17);background:rgba(6,23,29,.46);backdrop-filter:blur(8px);border-radius:5px}.reward-spark{color:var(--lime);font-size:21px}.daily-reward div{display:flex;flex-direction:column;gap:4px;flex:1}.daily-reward b{font:600 9px 'DM Mono';letter-spacing:1px}.daily-reward small{font-size:10px;color:#a8bab4}.daily-reward button{border:0;background:none;color:var(--lime);font:600 9px 'DM Mono';letter-spacing:.8px}.daily-reward button span{font-size:10px}.lobby-right{position:absolute;right:9.6%;top:22%;width:235px;display:flex;flex-direction:column;gap:12px}.season-card{height:210px;padding:17px 18px;position:relative;overflow:hidden;border:1px solid rgba(232,246,231,.24);border-radius:5px;background:linear-gradient(150deg,rgba(236,165,100,.27),rgba(8,38,47,.72) 58%),radial-gradient(ellipse at 80% 22%,#df9169,transparent 58%);box-shadow:0 10px 40px rgba(0,0,0,.2)}.season-card:before{content:'';position:absolute;right:-21px;top:51px;width:142px;height:142px;border-radius:50%;border:1px solid rgba(255,235,202,.29);box-shadow:0 0 0 13px rgba(255,235,202,.045),0 0 0 28px rgba(255,235,202,.035)}.season-card:after{content:'';position:absolute;right:18px;bottom:40px;width:95px;height:2px;background:linear-gradient(90deg,transparent,#ffbf83);transform:rotate(-20deg)}.season-top,.season-bottom{display:flex;align-items:center;justify-content:space-between;font:500 8px 'DM Mono';letter-spacing:1px;color:#f5e9d8;position:relative;z-index:1}.season-live{display:flex;align-items:center;gap:6px;color:var(--lime)}.season-live i{width:5px;height:5px}.season-title{position:relative;z-index:1;margin-top:27px;font:700 24px/.95 'Space Grotesk';letter-spacing:-1px}.season-bottom{position:absolute;left:18px;right:18px;bottom:15px;color:#b9c9c0}.season-bottom b{color:#f4f4e9;font-weight:500}.season-arrow{font:16px 'DM Sans';color:var(--lime)}.mode-card{height:68px;padding:0 12px;display:flex;align-items:center;gap:11px;background:rgba(5,22,28,.76);border:1px solid rgba(235,247,232,.16);border-radius:5px;backdrop-filter:blur(8px)}.mode-icon{width:31px;height:31px;border-radius:50%;display:grid;place-items:center;color:var(--lime);background:rgba(216,255,100,.1);font-size:23px}.mode-card>div:nth-child(2){flex:1;display:flex;flex-direction:column;gap:4px}.mode-card b{font:600 8px 'DM Mono';letter-spacing:.6px}.mode-card small{font-size:9px;color:#a4b7b1}.mode-card button{background:none;border:0;color:var(--lime);font-size:18px}.bottom-nav{position:absolute;bottom:66px;left:50%;transform:translateX(-50%);display:flex;gap:31px;padding:0 20px}.nav-item{border:0;background:none;color:#91aaa5;display:flex;align-items:center;gap:7px;font:500 9px 'DM Mono';letter-spacing:1px;padding:10px 1px;border-bottom:1px solid transparent}.nav-item span{font-size:17px}.nav-item.active{color:var(--lime);border-color:var(--lime)}.game-footer{position:absolute;z-index:4;bottom:0;left:5.2%;right:5.2%;height:42px;border-top:1px solid rgba(231,244,227,.12);display:flex;align-items:center;justify-content:space-between;color:#809893;font:500 8px 'DM Mono';letter-spacing:1.2px}.game-footer button{border:0;background:none;color:#a9c1ba;font:500 8px 'DM Mono';letter-spacing:1px;padding:10px 0}.game-footer button:hover{color:var(--lime)}
/* court selection */
.setup{padding:105px 10% 86px;background:linear-gradient(90deg,rgba(5,21,28,.9),rgba(5,21,28,.72) 62%,rgba(5,21,28,.38))}.panel-head{display:flex;align-items:center;gap:17px}.back-btn{width:38px;height:38px;border-radius:50%;border:1px solid var(--line);background:rgba(8,30,36,.55);font-size:19px;color:var(--ink);display:grid;place-items:center}.panel-head .eyebrow{margin-bottom:5px}.panel-head h2{margin:0;font:600 29px 'Space Grotesk';letter-spacing:-1px}.step-label{margin-left:auto;color:#d4dfd4;font:500 11px 'DM Mono';letter-spacing:1px}.step-label i{font-style:normal;color:#6b8781}.map-grid{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));gap:15px;margin-top:39px;max-width:1030px}.map-card{height:265px;position:relative;overflow:hidden;border:1px solid rgba(226,243,226,.21);border-radius:6px;text-align:left;background:#174d53;padding:0;transition:.2s}.map-card:hover{transform:translateY(-5px);border-color:rgba(216,255,100,.7)}.map-card.selected{border:2px solid var(--lime);box-shadow:0 0 0 2px rgba(216,255,100,.1)}.map-art{position:absolute;inset:0;overflow:hidden}.map-art:before{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(5,25,30,.08),rgba(5,25,30,.1) 44%,rgba(4,18,23,.88))}.map-art:after{content:'';position:absolute;left:13%;right:13%;bottom:45px;height:83px;clip-path:polygon(15% 0,85% 0,100% 100%,0 100%);background:repeating-linear-gradient(90deg,transparent 0 32%,rgba(255,255,255,.55) 32.5% 33%,transparent 33.5% 66%),linear-gradient(180deg,rgba(255,255,255,.09),rgba(255,255,255,.03));border:1px solid rgba(255,255,255,.5)}.map-art .sun{position:absolute;width:55px;height:55px;border-radius:50%;right:22px;top:34px;background:radial-gradient(circle,#fff2be,#ffb16d 66%,rgba(250,148,94,.05) 70%);box-shadow:0 0 40px rgba(255,177,109,.62)}.map-art .horizon{position:absolute;bottom:70px;left:-10%;width:120%;height:62px;background:linear-gradient(160deg,transparent 0 25%,rgba(17,67,65,.7) 25% 35%,transparent 35%),linear-gradient(190deg,transparent 0 33%,rgba(15,77,73,.8) 34% 50%,transparent 51%)}.map-card[data-map="sunset"] .map-art{background:linear-gradient(180deg,#e89575,#e1b080 41%,#cfaa75 42%,#c89560)}.map-card[data-map="ice"] .map-art{background:linear-gradient(180deg,#82c5d5,#c6e7dc 48%,#84bdc6 49%,#5497a4)}.map-card[data-map="neon"] .map-art{background:linear-gradient(180deg,#261959,#6337a4 45%,#d74988 46%,#351e75)}.map-card[data-map="tropic"] .map-art{background:linear-gradient(180deg,#55bec5,#b5e3b0 44%,#82bc75 45%,#39816e)}.map-card[data-map="ice"] .sun{background:radial-gradient(circle,#f0ffff,#acf2f4 60%,transparent 70%);box-shadow:0 0 40px #d1ffff}.map-card[data-map="neon"] .sun{background:radial-gradient(circle,#ffd4f4,#fd70c3 55%,transparent 72%);box-shadow:0 0 42px #f554e0}.map-card[data-map="tropic"] .sun{background:radial-gradient(circle,#faffb8,#f0db70 60%,transparent 70%);box-shadow:0 0 36px #f9e89a}.map-card .map-info{position:absolute;z-index:1;left:16px;right:12px;bottom:14px}.map-info .map-tag{display:block;color:var(--lime);font:500 8px 'DM Mono';letter-spacing:1.2px;margin-bottom:7px}.map-info strong{display:block;font:600 18px 'Space Grotesk';letter-spacing:-.3px}.map-info small{display:block;color:#cad8cf;font-size:10px;margin-top:4px}.map-check{position:absolute;z-index:2;right:12px;top:12px;border-radius:50%;width:22px;height:22px;background:var(--lime);color:#162923;display:none;place-items:center;font-size:13px}.map-card.selected .map-check{display:grid}.locked-stamp{position:absolute;z-index:2;top:12px;left:12px;padding:5px 7px;background:rgba(4,19,24,.7);border-radius:3px;color:#e0e8d9;font:8px 'DM Mono';letter-spacing:.5px}.setup-footer{position:absolute;left:10%;right:10%;bottom:37px;display:flex;align-items:center;justify-content:space-between}.setup-hint{font:9px 'DM Mono';letter-spacing:.7px;color:#a2b9b1}.setup-hint span{font-size:15px;margin-right:8px;color:var(--teal)}.setup-hint b{font-weight:500;color:#e7f0e4;margin-left:5px}.setup-hint i{font-style:normal;margin:0 8px;color:#627a76}.setup-footer .primary-btn{min-width:180px}
/* online modal */
.online-panel{inset:12% 50% auto auto;transform:translateX(50%);width:min(710px,90vw);padding:27px 31px 24px;background:rgba(6,24,31,.96);border:1px solid rgba(228,243,226,.2);border-radius:8px;box-shadow:0 25px 100px #020d13;backdrop-filter:blur(18px)}.online-panel .panel-head{margin-bottom:18px}.online-intro{max-width:510px;margin:0 0 20px 55px;color:#b2c3bd;font-size:12px;line-height:1.6}.online-options{margin-left:55px;display:grid;grid-template-columns:1fr 1fr;gap:13px}.online-option{min-height:201px;padding:18px;background:rgba(241,248,229,.045);border:1px solid rgba(228,243,226,.13);border-radius:5px}.online-symbol{color:var(--lime);font-size:23px}.online-option h3{margin:8px 0 4px;font:600 15px 'Space Grotesk'}.online-option p{height:29px;margin:0 0 11px;color:#9fb3ac;font-size:10px}.outline-btn{height:34px;padding:0 15px;background:transparent;border:1px solid rgba(216,255,100,.6);border-radius:3px;color:var(--lime);font:500 9px 'DM Mono';letter-spacing:1px}.outline-btn:hover{background:rgba(216,255,100,.1)}.room-code{position:relative;margin-top:8px;display:grid;grid-template-columns:1fr auto;gap:3px}.room-code>span,.room-code small{grid-column:1;font:8px 'DM Mono';letter-spacing:1px;color:#9fb3ac}.room-code strong{font:600 16px 'DM Mono';letter-spacing:2px;color:var(--lime)}.room-code button{grid-column:2;grid-row:1/3;align-self:center;background:none;border:1px solid var(--line);border-radius:3px;padding:6px;color:#e5eee4;font:8px 'DM Mono'}.room-code small{font-size:8px;letter-spacing:.2px;margin-top:4px}.join-row{display:flex;gap:6px}.join-row input{min-width:0;width:100%;height:34px;padding:0 9px;border:1px solid rgba(227,242,225,.2);border-radius:3px;background:rgba(2,14,20,.65);color:white;outline:none;font:10px 'DM Mono';letter-spacing:1px;text-transform:uppercase}.join-row input:focus{border-color:var(--teal)}.connection-note{display:block;margin-top:12px;color:#829892;font-size:9px}.online-footnote{margin:17px 0 0 55px;color:#829892;font-size:9px}
/* in match */
.game-ui{pointer-events:none}.game-ui button,.game-ui .touch-controls{pointer-events:auto}.game-top{position:absolute;top:82px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:22px;padding:10px 16px;border:1px solid rgba(240,248,230,.2);background:rgba(4,21,27,.73);border-radius:5px;backdrop-filter:blur(9px);white-space:nowrap}.leave-btn{width:30px;height:30px;font-size:19px}.map-name{display:flex;align-items:center;gap:7px;font:500 9px 'DM Mono';letter-spacing:1px;color:#c4d2c8}.map-dot{width:6px;height:6px;border-radius:50%;background:var(--lime)}.scoreboard{display:flex;align-items:center;gap:11px;padding:0 17px;border-left:1px solid var(--line);border-right:1px solid var(--line)}.score-side{display:flex;align-items:center;gap:7px}.score-side small{font:8px 'DM Mono';letter-spacing:.7px;color:#a9bbb2}.score-side b{font:600 19px 'Space Grotesk';color:white}.score-divider{font:12px 'DM Mono';color:#6e8781}.match-set{font:8px 'DM Mono';letter-spacing:.7px;color:var(--lime)}.game-hint{position:absolute;top:150px;left:50%;transform:translateX(-50%);color:#e7e9d9;padding:7px 12px;background:rgba(5,21,26,.55);border-radius:20px;font:10px 'DM Mono';letter-spacing:.3px;white-space:nowrap}.game-hint span{color:var(--lime);font-weight:600}.toast{position:absolute;top:29%;left:50%;transform:translate(-50%,-10px);opacity:0;color:var(--lime);font:700 34px 'Space Grotesk';letter-spacing:3px;text-shadow:0 3px 20px #06141b;transition:.25s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.touch-controls{display:none;position:absolute;bottom:66px;left:23px;right:23px;align-items:flex-end;justify-content:space-between}.dpad{width:136px;height:112px;position:relative}.dpad button{position:absolute;width:39px;height:39px;border:1px solid rgba(239,249,228,.45);border-radius:8px;background:rgba(4,21,27,.58);font-size:17px;touch-action:none}.dpad button:nth-child(1){left:0;top:36px}.dpad button:nth-child(2){left:48px;top:0}.dpad button:nth-child(3){left:48px;top:72px}.dpad button:nth-child(4){right:0;top:36px}.hit-btn{width:76px;height:76px;border:1px solid var(--lime);border-radius:50%;background:rgba(216,255,100,.19);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;touch-action:none}.hit-btn span{font-size:24px;line-height:22px;color:var(--lime)}.hit-btn b{font:600 9px 'DM Mono';letter-spacing:1px}.modal{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:rgba(3,16,21,.58);backdrop-filter:blur(6px)}.result-card{width:min(370px,88vw);padding:30px 34px 28px;text-align:center;border:1px solid rgba(229,243,222,.2);border-radius:7px;background:radial-gradient(ellipse at 50% 0,rgba(83,133,103,.25),transparent 48%),#0a222b;box-shadow:0 25px 90px rgba(0,0,0,.45)}.result-burst{width:45px;height:45px;margin:0 auto 15px;border-radius:50%;display:grid;place-items:center;color:#14251e;background:var(--lime);font-size:24px;box-shadow:0 0 25px rgba(216,255,100,.25)}.result-card .eyebrow{margin-bottom:9px}.result-card h2{margin:0;font:700 43px/.9 'Space Grotesk';letter-spacing:-2px}.result-card>p:not(.eyebrow){color:#aabbb3;font-size:12px;margin:12px 0 19px}.result-reward{padding:11px 14px;display:flex;align-items:center;gap:10px;text-align:left;background:rgba(233,244,222,.06);border:1px solid rgba(233,244,222,.1);border-radius:4px;margin-bottom:17px}.result-reward>span:first-child{font-size:20px;color:var(--lime)}.result-reward div{display:flex;flex-direction:column;gap:2px;flex:1}.result-reward small{font:8px 'DM Mono';letter-spacing:.8px;color:#9fb2a9}.result-reward b{font:600 16px 'Space Grotesk';color:var(--lime)}.result-reward>span:last-child{font:8px 'DM Mono';color:#9fb2a9}.result-card .primary-btn{width:100%}.toast-global{position:absolute;z-index:10;left:50%;bottom:57px;transform:translate(-50%,15px);padding:10px 17px;background:#d8ff64;color:#112620;border-radius:4px;font:600 10px 'DM Mono';letter-spacing:.4px;opacity:0;pointer-events:none;transition:.2s}.toast-global.show{opacity:1;transform:translate(-50%,0)}
